{
  "name": "Equipment Change Process",
  "resources": [
    {
      "name": "MPON",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "MPOO",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "GO",
      "capacity": 1,
      "resource_type": "department"
    },
    {
      "name": "MSP",
      "capacity": 1,
      "resource_type": "external_party"
    }
  ],
  "events": [
    {
      "id": "evt_start_mpon",
      "name": "Equipment change intended",
      "event_position": "start",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "evt_msg_mpoo_start",
      "name": "Intent received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Equipment change intention"
    },
    {
      "id": "evt_msg_mpoo_end",
      "name": "Dismount decision sent",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Self dismounting decision"
    },
    {
      "id": "evt_msg_mpon_rec_dec",
      "name": "Dismount decision received",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Self dismounting decision"
    },
    {
      "id": "evt_go_start",
      "name": "Final reading received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Final reading values"
    },
    {
      "id": "evt_go_rec_changes",
      "name": "Device changes received",
      "event_position": "intermediate",
      "trigger_type": "message",
      "message_name": "Device changes and installation data"
    },
    {
      "id": "evt_go_end",
      "name": "Data sent to MSP",
      "event_position": "end",
      "trigger_type": "message",
      "message_name": "Device changes, master data and counts"
    },
    {
      "id": "evt_msp_start",
      "name": "Notification received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Device changes, master data and counts"
    },
    {
      "id": "evt_msp_end",
      "name": "Process finished in MSP",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_notify_mpoo",
      "name": "Notify MPOO about equipment change intentions",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_announce_self_dismount",
      "name": "Announce self dismounting to MPON",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MPOO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_notify_no_self_dismount",
      "name": "Notify MPON about no self-dismounting",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MPOO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_mpoo_final_reading",
      "name": "Perform final reading (MPOO)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPOO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["doc_final_reading"]
    },
    {
      "id": "task_mpoo_dismount",
      "name": "Dismount old equipment (MPOO)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPOO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_mpon_final_reading",
      "name": "Perform final reading (MPON)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["doc_final_reading"]
    },
    {
      "id": "task_mpon_dismount",
      "name": "Dismount old equipment (MPON)",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_mpon_mount",
      "name": "Mount new device",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_mpon_read_installed",
      "name": "Read meter count from installed meter",
      "bpmn_type": "bpmn:ManualTask",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["doc_installation_count"]
    },
    {
      "id": "task_mpon_send_final_reading",
      "name": "Send values of final reading to GO",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_final_reading"],
      "output_data_ids": []
    },
    {
      "id": "task_mpon_tell_go_changes",
      "name": "Tell GO about device changes, master data and meter count at installation",
      "bpmn_type": "bpmn:Task",
      "resource_name": "MPON",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_installation_count", "doc_master_data"],
      "output_data_ids": []
    },
    {
      "id": "task_go_notify_msp",
      "name": "Notify MSP about device changes, master data, meter count at dismounting, and meter count at installation",
      "bpmn_type": "bpmn:Task",
      "resource_name": "GO",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["doc_final_reading", "doc_installation_count", "doc_master_data"],
      "output_data_ids": []
    }
  ],
  "gateways": [
    {
      "id": "gw_mpoo_decide_dismount",
      "name": "Self dismounting?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_mpoo_gw_to_self",
          "condition": "Self dismounting"
        },
        {
          "flow_id": "sf_mpoo_gw_to_no_self",
          "condition": "No self dismounting"
        }
      ]
    },
    {
      "id": "gw_mpoo_join_dec",
      "name": "Dismount decision join",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_mpon_check_dismount_by",
      "name": "Who dismounts?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "sf_mpon_gw_to_mpon_dismount",
          "condition": "No self dismounting by MPOO"
        },
        {
          "flow_id": "sf_mpon_gw_to_mount",
          "condition": "Self dismounted by MPOO"
        }
      ]
    },
    {
      "id": "gw_mpon_join_dismount",
      "name": "Dismount completed join",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "sf_mpon_1",
      "source_id": "evt_start_mpon",
      "target_id": "task_notify_mpoo"
    },
    {
      "id": "sf_mpon_2",
      "source_id": "task_notify_mpoo",
      "target_id": "evt_msg_mpon_rec_dec"
    },
    {
      "id": "sf_mpon_3",
      "source_id": "evt_msg_mpon_rec_dec",
      "target_id": "gw_mpon_check_dismount_by"
    },
    {
      "id": "sf_mpon_gw_to_mpon_dismount",
      "source_id": "gw_mpon_check_dismount_by",
      "target_id": "task_mpon_final_reading",
      "condition_name": "No self dismounting by MPOO"
    },
    {
      "id": "sf_mpon_4",
      "source_id": "task_mpon_final_reading",
      "target_id": "task_mpon_dismount"
    },
    {
      "id": "sf_mpon_5",
      "source_id": "task_mpon_dismount",
      "target_id": "gw_mpon_join_dismount"
    },
    {
      "id": "sf_mpon_gw_to_mount",
      "source_id": "gw_mpon_check_dismount_by",
      "target_id": "gw_mpon_join_dismount",
      "condition_name": "Self dismounted by MPOO"
    },
    {
      "id": "sf_mpon_6",
      "source_id": "gw_mpon_join_dismount",
      "target_id": "task_mpon_mount"
    },
    {
      "id": "sf_mpon_7",
      "source_id": "task_mpon_mount",
      "target_id": "task_mpon_read_installed"
    },
    {
      "id": "sf_mpon_8",
      "source_id": "task_mpon_read_installed",
      "target_id": "task_mpon_send_final_reading"
    },
    {
      "id": "sf_mpon_9",
      "source_id": "task_mpon_send_final_reading",
      "target_id": "task_mpon_tell_go_changes"
    },
    {
      "id": "sf_mpoo_1",
      "source_id": "evt_msg_mpoo_start",
      "target_id": "gw_mpoo_decide_dismount"
    },
    {
      "id": "sf_mpoo_gw_to_self",
      "source_id": "gw_mpoo_decide_dismount",
      "target_id": "task_mpoo_final_reading",
      "condition_name": "Self dismounting"
    },
    {
      "id": "sf_mpoo_2",
      "source_id": "task_mpoo_final_reading",
      "target_id": "task_mpoo_dismount"
    },
    {
      "id": "sf_mpoo_3",
      "source_id": "task_mpoo_dismount",
      "target_id": "task_announce_self_dismount"
    },
    {
      "id": "sf_mpoo_4",
      "source_id": "task_announce_self_dismount",
      "target_id": "gw_mpoo_join_dec"
    },
    {
      "id": "sf_mpoo_gw_to_no_self",
      "source_id": "gw_mpoo_decide_dismount",
      "target_id": "task_notify_no_self_dismount",
      "condition_name": "No self dismounting"
    },
    {
      "id": "sf_mpoo_5",
      "source_id": "task_notify_no_self_dismount",
      "target_id": "gw_mpoo_join_dec"
    },
    {
      "id": "sf_mpoo_6",
      "source_id": "gw_mpoo_join_dec",
      "target_id": "evt_msg_mpoo_end"
    },
    {
      "id": "sf_go_1",
      "source_id": "evt_go_start",
      "target_id": "evt_go_rec_changes"
    },
    {
      "id": "sf_go_2",
      "source_id": "evt_go_rec_changes",
      "target_id": "task_go_notify_msp"
    },
    {
      "id": "sf_go_3",
      "source_id": "task_go_notify_msp",
      "target_id": "evt_go_end"
    },
    {
      "id": "sf_msp_1",
      "source_id": "evt_msp_start",
      "target_id": "evt_msp_end"
    }
  ],
  "pools": [
    {
      "id": "pool_mpon",
      "name": "MPON",
      "element_ids": [
        "evt_start_mpon",
        "task_notify_mpoo",
        "evt_msg_mpon_rec_dec",
        "gw_mpon_check_dismount_by",
        "task_mpon_final_reading",
        "task_mpon_dismount",
        "gw_mpon_join_dismount",
        "task_mpon_mount",
        "task_mpon_read_installed",
        "task_mpon_send_final_reading",
        "task_mpon_tell_go_changes"
      ]
    },
    {
      "id": "pool_mpoo",
      "name": "MPOO",
      "element_ids": [
        "evt_msg_mpoo_start",
        "gw_mpoo_decide_dismount",
        "task_mpoo_final_reading",
        "task_mpoo_dismount",
        "task_announce_self_dismount",
        "task_notify_no_self_dismount",
        "gw_mpoo_join_dec",
        "evt_msg_mpoo_end"
      ]
    },
    {
      "id": "pool_go",
      "name": "GO",
      "element_ids": [
        "evt_go_start",
        "evt_go_rec_changes",
        "task_go_notify_msp",
        "evt_go_end"
      ]
    },
    {
      "id": "pool_msp",
      "name": "MSP",
      "element_ids": [
        "evt_msp_start",
        "evt_msp_end"
      ]
    }
  ],
  "message_flows": [
    {
      "id": "mf_mpon_to_mpoo_intent",
      "source_id": "task_notify_mpoo",
      "target_id": "evt_msg_mpoo_start",
      "name": "Equipment change intention"
    },
    {
      "id": "mf_mpoo_to_mpon_dec",
      "source_id": "evt_msg_mpoo_end",
      "target_id": "evt_msg_mpon_rec_dec",
      "name": "Self dismounting decision"
    },
    {
      "id": "mf_mpon_to_go_final_read",
      "source_id": "task_mpon_send_final_reading",
      "target_id": "evt_go_start",
      "name": "Final reading values"
    },
    {
      "id": "mf_mpon_to_go_changes",
      "source_id": "task_mpon_tell_go_changes",
      "target_id": "evt_go_rec_changes",
      "name": "Device changes, master data and installation count"
    },
    {
      "id": "mf_go_to_msp",
      "source_id": "evt_go_end",
      "target_id": "evt_msp_start",
      "name": "Device changes, master data, dismounting and installation counts"
    }
  ],
  "data_objects": [
    {
      "id": "doc_final_reading",
      "name": "Final Reading / Dismounting Meter Count"
    },
    {
      "id": "doc_installation_count",
      "name": "Installation Meter Count"
    },
    {
      "id": "doc_master_data",
      "name": "Master Data"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "hours"
}
